function nativeAppIcon(id){if(['clock','internet','calendar','settings','drive','google'].includes(id))return `<img class="real-app-icon" src="assets/icon-${id}-clean.svg" alt="">`;if(iconAssets.has(id))return `<img class="real-app-icon" src="assets/icon-${id}.png" alt="">`;if(id==='naver')return 'N';if(id==='chrome')return '<span class="chrome-icon"></span>';return nativeIcon(id==='mail'?'mail':id==='notes'?'notes':id)}
function nativeAppButton(id,label=true){const name=nativeApps.find(a=>a[0]===id)?.[1]||id,app={messages:'sms',naver:'news',internet:'internet',chrome:'internet',google:'internet'}[id]||id;return `<button class="app-button" data-native-app="${id}" aria-label="${name}"><span class="app-icon ${id}">${nativeAppIcon(id)}</span>${label?`<span class="app-label">${name}</span>`:''}${countBadge(unread(app))}</button>`}
function fitFold(){const vw=window.innerWidth,vh=window.innerHeight,opened=$('#device').classList.contains('folded-open');const availableWidth=vw<700?vw-24:opened?vw-(vw>1100?390:50):380;const maxH=Math.min(820,vh-(vw<700?56:108)),ratio=opened?1968/2184:1080/2520;const h=Math.max(320,Math.min(maxH-16,(availableWidth-16)/ratio));$('#device').style.setProperty('--display-h',h+'px');$('#device').style.setProperty('--display-ratio',ratio);$('#device').classList.toggle('compact',h<670)}
function toggleFold(){const d=$('#device');d.classList.toggle('folded-open');$('#foldBtn').innerHTML=d.classList.contains('folded-open')?'<span>▯</span> 접어 보기':'<span>▣</span> 펼쳐 보기';fitFold()}
function beginUnlock(target=null){pending=target;pin='';route={app:'pin'};$('#shade').hidden=true;hideBanner();render()}
function renderPin(error=false){return `<div class="pin-screen"><h2 class="pin-heading">PIN 입력</h2><div class="pin-hint ${error?'pin-error':''}">${error?'PIN이 올바르지 않습니다. 다시 입력하세요.':'휴대전화의 잠금을 해제하려면 PIN을 입력하세요.'}</div><div class="birthday-hint-v8">♥ 생일</div><div class="pin-dots">${[0,1,2,3].map(i=>`<span class="pin-dot ${i<pin.length?'filled':''}"></span>`).join('')}</div><div class="keypad">${[1,2,3,4,5,6,7,8,9,'',0,'⌫'].map((n,i)=>n===''?'<span></span>':`<button data-pin="${n}" aria-label="${n==='⌫'?'한 자리 지우기':n}">${n}<small>${['','ABC','DEF','GHI','JKL','MNO','PQRS','TUV','WXYZ'][i]||' '}</small></button>`).join('')}</div><div class="pin-footer"><button data-action="emergency">긴급전화</button><button data-action="lock">취소</button></div></div>`}
function pinKey(k){if(k==='⌫')pin=pin.slice(0,-1);else if(pin.length<4)pin+=k;if(pin.length===4){if(pin==='0613'){start();state.unlocked=true;const target=pending;pending=null;navigate(target==='source'?'sms-detail':target==='company'?'chat':'home',target==='source'?'source':target==='company'?'company':undefined,true);if(!target){const item=state.items.filter(x=>x.app==='sms'&&x.thread==='source').at(-1);if(item){bannerQueue.push(item);showNextBanner()}}return}pin='';$('#view').innerHTML=renderPin(true);return}$('#view').innerHTML=renderPin()}
function lockDevice(){state.unlocked=false;route={app:'lock'};history=[];hideBanner();bannerQueue=[];$('#shade').hidden=true;render();save()}
function syncNativeTheme(){const transparent=['home','lock','pin','drawer','recents'].includes(route.app);const color=transparent?'#fff':route.app==='chat'?'#23343e':'#222';const bg=transparent?'transparent':route.app==='chat'?'#b9cbd9':'#fff';$('#statusbar').style.color=color;$('#statusbar').style.background=bg;$('#systemNav').style.color=color;$('#systemNav').style.background=bg;$('#systemNav').style.visibility=['lock','pin'].includes(route.app)?'hidden':'visible';$('#view').classList.toggle('is-home',transparent);$('#under-time').textContent=clock();$('#top-notice').textContent=state.quiet?'☾':'▣'}
function openNativeApp(id){const app={messages:'sms',internet:'internet',naver:'news',chrome:'internet',google:'internet',kakao:'kakao',mail:'mail'}[id];if(app){if(app==='news')openNews(0,false);else navigate(app);return}if(id==='settings'){openShade();state.settings=true;renderShade();return}toast('지금은 뉴스와 도착한 연락부터 확인하자.')}
function openShade(){if(!state.unlocked)return;$('#shade').hidden=false;hideBanner();bannerQueue=[];renderShade()}
function nativeKakaoTabs(){return `<nav class="app-tabs">${[['person','친구'],['chat','채팅'],['heart','업데이트'],['more','더보기']].map(([ic,n])=>`<button ${n==='채팅'?'class="active" data-app="kakao"':'disabled'}>${nativeIcon(ic)}${n}</button>`).join('')}</nav>`}
function renderDrawer(){return `<div class="drawer"><div class="app-grid">${nativeApps.map(([id])=>nativeAppButton(id)).join('')}</div><div class="drawer-search"><span style="font-size:11px;opacity:.7">지금은 뉴스 · 카카오톡 · 메시지 · 메일</span></div></div>`}

function pruneFlood(){const flood=state.items.filter(x=>x.id.startsWith('flood-'));if(flood.length<=180)return;const evicted=new Set(flood.slice(0,flood.length-180).map(x=>x.id));state.items=state.items.filter(x=>!evicted.has(x.id));state.notifications=state.notifications.filter(id=>!evicted.has(id));for(const id of evicted)delete state.read[id]}
function save(){}
function clock(){let m=Math.floor(state.elapsed/STORY_MINUTE_SECONDS);return `${String(Math.floor(m/60)%24).padStart(2,'0')}:${String(m%60).padStart(2,'0')}`}
function stamp(at){let m=Math.floor(at/STORY_MINUTE_SECONDS);return `${String(Math.floor(m/60)%24).padStart(2,'0')}:${String(m%60).padStart(2,'0')}`}
function avatar(p){return `<span class="profile ${p===people.company?'company':p===people.yechan?'yechan':p===people.wonsang?'wonsang':p===people.gwangil?'gwangil':'group'}">${p.photo?`<img src="${p.photo}" alt="${esc(p.name)}">`:esc(p.mark||'·')}</span>`}
function icon(app){return app==='kakao'?'<span class="mini-icon kakao">●</span>':`<span class="mini-icon">${{news:'N',sms:'▤',mail:'M'}[app]||'·'}</span>`}
function unread(app,thread){return state.items.filter(x=>x.app===app&&(!thread||x.thread===thread)&&!state.read[x.id]).length}
function countBadge(n){return n?`<span class="badge">${n>99?'99+':n}</span>`:''}
function header(title,small=''){return `<header class="bar"><button data-action="back" aria-label="뒤로">‹</button>${title}<small>${small}</small></header>`}
function navigate(app,arg,replace=false){if(!replace)history.push({...route});route={app,arg};$('#shade').hidden=true;state.settings=false;markRead();render();if(app==='chat'&&$('#chat-scroll'))$('#chat-scroll').scrollTop=$('#chat-scroll').scrollHeight;else $('#view').scrollTop=0;save()}
function markRead(){let matches=[];if(route.app==='chat')matches=state.items.filter(x=>x.app==='kakao'&&x.thread===route.arg);if(route.app==='sms-detail')matches=state.items.filter(x=>x.app==='sms'&&x.thread===route.arg);if(route.app==='mail-detail')matches=state.items.filter(x=>x.id===route.arg);if(route.app==='news'||route.app==='article'||route.app==='community')matches=state.items.filter(x=>x.app==='news');matches.forEach(x=>state.read[x.id]=true)}
function openNotice(id){const item=state.items.find(x=>x.id===id);if(!item)return;state.read[id]=true;hideBanner();$('#shade').hidden=true;if(item.app==='kakao')navigate('chat',item.thread);else if(item.app==='sms')navigate('sms-detail',item.thread);else if(item.app==='mail')navigate('mail-detail',item.id);else openNews(item.article??0,true)}
function openNews(index,detail=false){if(!state.newsOpened){state.newsOpened=true;state.newsAt=state.elapsed;save()}navigate(detail?'article':'news',index)}
function home(){return `<div class="home"><div class="home-carousel"><section class="home-page page-primary"><div class="home-top"><button class="weather-widget" data-action="weather"><span class="weather-moon">☾</span><div class="degree">13°</div><small>서울특별시<br>맑음 · 최저 11° / 최고 20°</small><small style="margin-top:5px">10.26 오전 ${clock()}</small></button><div class="mini-widgets"><button class="date-widget" data-action="day">10월 26일 월요일<b>오늘도 좋은 하루</b></button><button class="schedule-widget" data-action="day">오늘의 일정<b>공연이 끝난 밤</b><span style="font-size:8px;opacity:.7">AFTER THE CONCERT</span></button></div></div><button class="search-widget" data-app="news" aria-label="뉴스 검색"><span class="google-g">G</span><span style="flex:1"></span><span style="font-size:15px">♩</span><span style="font-size:18px;margin-left:10px">⌘</span></button><div class="home-apps">${['kakao','bubble','music','gallery','calendar','notes','youtube','settings','recorder','files','clock','contact'].map(id=>nativeAppButton(id)).join('')}</div></section><section class="home-page page-tools"><h3>자주 쓰는 앱</h3><div class="home-apps">${['clock','calculator','recorder','files','contact','mail','maps','weather','health','playstore','drive','chrome'].map(id=>nativeAppButton(id)).join('')}</div><button class="home-note-widget" data-action="quiet-hint"><small>오늘의 밤</small><b>읽지 않은 연락</b><p>조용해지고 싶으면<br>상단 시계를 눌러 알림을 끄자.</p></button></section><section class="home-page page-music"><h3>오늘의 음악</h3><button class="home-note-widget" data-native-app="music"><img src="assets/yechan-cover.jpg" alt="자장가수"><small>YouTube Music</small><b>형이 커버한 노래 모음</b><p>잠들기 전에 한 곡 더</p></button><div class="home-apps">${['music','youtube','bubble','gallery'].map(id=>nativeAppButton(id)).join('')}</div></section></div><div class="dots">${[0,1,2].map(i=>`<button data-home-page="${i}" aria-label="홈 화면 ${i+1}" class="${i===homePage?'active':''}">●</button>`).join('')}</div><div class="dock">${['phone','messages','internet','camera'].map(id=>nativeAppButton(id,false)).join('')}</div><button class="drawer-button" data-action="drawer" aria-label="모든 앱 보기">⌃</button></div>`}
function lock(){const last=state.items.filter(x=>x.app==='sms'&&x.thread==='source').at(-1),text=last?.text||'최상엽 씨 본인 번호 맞으시죠? 사진 3장 보내드립니다.';const [h,m]=state.started?clock().split(':'):['00','00'];return `<div class="lock-screen lock-v3"><div class="lock-icon">${nativeIcon('lock')}</div><div class="lock-clock-group"><div class="lock-date">10월 26일 월요일</div><div class="lock-time"><span>${h}</span><span>${m}</span></div><div class="lock-weather">☾ 13°</div></div><button class="unlock-area" data-action="unlock" aria-label="잠금 해제"></button><button class="lock-notification" data-action="unlock-source" aria-label="모르는 번호 문자 알림 열기"><div class="notice-top"><span><span class="kakao-mini" style="background:#e5efff;color:#40597b">SMS</span> 메시지</span><span>${last?.time||'지금'}</span></div><div class="notice-name">010-****-1026</div><div class="notice-message">${esc(text)}</div></button><div class="lock-birthday-hint-v8">비밀번호 힌트 : ♥ 생일</div><div class="lock-bottom"><button data-action="unlock" aria-label="잠금 해제">${nativeIcon('phone')}</button><span data-action="unlock">화면을 밀어 잠금을 해제하세요</span><button data-action="unlock" aria-label="잠금 해제">${nativeIcon('camera')}</button></div></div>`}
function chatList(){const ids=Object.keys(people).sort((a,b)=>{const latest=id=>state.items.filter(x=>x.thread===id&&x.app==='kakao').at(-1)?.at??-1;return latest(b)-latest(a)});return `<section class="app-view kakao-view"><header class="app-header"><h2>채팅</h2><span style="font-size:19px;color:#222">${nativeIcon('search')}</span></header><div class="app-content"><div style="margin:0 16px 12px;color:#aaa;font-size:10px">2026년 10월 26일 · 월요일</div>${ids.map(id=>{const p=people[id],last=state.items.filter(x=>x.app==='kakao'&&x.thread===id).at(-1);return `<button class="chat-list-row" data-chat="${id}">${avatar(p)}<div class="chat-details"><b>${p.name}</b><p>${esc(last?.text||({yechan:'오늘 수고했어, 엽아.',wonsang:'형 잘 들어갔어?',gwangil:'형 푹 쉬어',group:'막콘도 수고했어!'}[id]||'회사에서 온 메시지'))}</p></div><span class="chat-meta">${last?.time||'10/25'}${unread('kakao',id)?`<span class="unread">${unread('kakao',id)}</span>`:''}</span></button>`}).join('')}</div>${nativeKakaoTabs()}</section>`}
function chat(id){const p=people[id],items=state.items.filter(x=>x.app==='kakao'&&x.thread===id),prior={company:[],yechan:[['예찬이형♥','잘 들어갔어? 오늘 수고했어 엽아'],['나','어 형 나 씻고 나올게']],wonsang:[['원상이','형 잘 들어갔어? 오늘 좋았다']],gwangil:[['광일이','형 푹 쉬어 나 이제 집']],group:[['광일','형들 수고했어!'],['원상','오늘 좋았다 다들 푹 쉬어']]}[id]||[];return `<section class="app-view chat-room"><header class="app-header"><button class="icon-btn" data-action="back" aria-label="대화 목록으로">${nativeIcon('back')}</button><h2 class="chat-title">${p.name}</h2><span style="font-size:10px;color:#60717b">${id==='group'?'4':''}</span><span>${nativeIcon('more')}</span></header><div class="chat-scroll" id="chat-scroll">${prior.length?'<div class="chat-date">2026년 10월 25일 일요일</div>'+prior.map(([n,t])=>msg({sender:n,text:t,time:'23:58'},p)).join(''):''}<div class="chat-date">2026년 10월 26일 월요일</div>${items.map(x=>msg(x,p)).join('')}</div><div class="composer"><span>＋</span><div class="reply-paused">지금은 답장을 잠시 미뤄 두자.</div><span>☺</span></div></section>`}
function msg(x,p){const mine=x.sender==='나';const member=p===people.group?({'원상':people.wonsang,'광일':people.gwangil,'예찬이형♥':people.yechan}[x.sender]||p):p;return `<div class="message ${mine?'mine':''}">${mine?'':avatar(member)}<div class="msg-body">${mine?'':`<div class="sender-name">${esc(x.sender)}</div>`}<div class="bubble-line"><div class="bubble">${esc(x.text)}</div><time class="msg-time">${x.time}</time></div></div></div>`}
function smsList(){const arr=state.items.filter(x=>x.app==='sms'),threads=[...new Set(arr.slice().reverse().map(x=>x.thread))];return `<section class="app-view sms-view"><header class="app-header"><span style="margin-left:auto;color:#777">⋮</span></header><div class="sms-hero">메시지<span>알 수 없는 발신자 ${threads.length}명</span></div><div class="app-content">${threads.length?threads.map(id=>{const x=arr.filter(x=>x.thread===id).at(-1);return `<button class="chat-list-row" data-sms="${id}"><span class="profile">${nativeIcon('person')}</span><div class="chat-details"><b>${unread('sms',id)?'<i class="unread-dot"></i>':''}${esc(x.sender)}</b><p>${esc(x.text)}</p></div><span class="sms-row-date">${x.time}</span></button>`}).join(''):'<div class="empty">아직 도착한 메시지가 없다.</div>'}</div></section>`}
function smsDetail(id){const items=state.items.filter(x=>x.app==='sms'&&x.thread===id);return `<div class="page">${header(esc(items[0]?.sender||'알 수 없는 발신자'),'연락처에 없음')}<div class="sms-detail"><div class="sms-day">2026년 10월 26일 월요일</div>${items.map(x=>`<div class="sms-bubble">${esc(x.text)}${x.attachment?'<div class="photo-attachments" aria-label="발신자가 보낸 사진 첨부 3장"><span>입 맞추는 사진<br><small>미리보기 1/3</small></span><span>사진 2<br><small>미리보기 2/3</small></span><span>사진 3<br><small>미리보기 3/3</small></span></div>':''}</div><div class="news-meta">${x.time}</div>`).join('')}<p class="sms-notice">연락처에 저장되지 않은 발신자이다.<br>지금은 답장을 보내지 않았다.</p></div></div>`}
function mailList(){const arr=state.items.filter(x=>x.app==='mail').slice().reverse();return `<div class="page"><h2 class="page-title">받은메일함</h2><div class="subline">읽지 않은 메일 ${unread('mail')}개 · sangyeop@phone.example</div>${arr.length?arr.map(x=>`<button class="row mail-row" data-mail="${x.id}"><span class="avatar mail-initial">${esc(x.sender[0])}</span><div><strong>${!state.read[x.id]?'<i class="unread-dot"></i>':''}${esc(x.sender)}</strong><div class="subject">${esc(x.title)}</div><p>${esc(x.text)}</p></div><span class="row-end">${x.time}</span></button>`).join(''):'<div class="empty">아직 도착한 메일이 없다.</div>'}</div>`}
function mailDetail(id){const x=state.items.find(x=>x.id===id);if(!x)return mailList();return `<div class="page">${header('메일','받은메일함')}<article class="mail-detail"><h2>${esc(x.title)}</h2><div class="mail-person"><span class="avatar mail-initial">${esc(x.sender[0])}</span><div>${esc(x.sender)}<br><small>&lt;${esc(x.email)}&gt;<br>받는 사람: sangyeop@phone.example<br>2026.10.26 ${x.time}</small></div></div><div class="mail-body">${esc(x.text)}</div><span class="mail-tag">연락처에 없는 발신자</span></article></div>`}
